"""Minimal standard-library client for private text prompts.

Usage::

    from openai_client import send_prompt

    answer = send_prompt("Summarize this text", model="gpt-4.1-mini")

The API key is read from ``OPENAI_API_KEY`` unless supplied explicitly. Prompt
and response contents are never logged or written to disk. Requests set
``store=False`` so Responses API output is not stored for later retrieval.
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any, Mapping, Optional


API_URL = "https://api.openai.com/v1/responses"


class OpenAIError(Exception):
    """Base class for errors raised by this module."""


class OpenAIConfigurationError(OpenAIError):
    """Raised when the client configuration is invalid."""


class OpenAIAPIError(OpenAIError):
    """Raised when the OpenAI API returns an error response."""


def send_prompt(
    prompt: str,
    *,
    model: str,
    api_key: Optional[str] = None,
    instructions: Optional[str] = None,
    max_output_tokens: Optional[int] = None,
    timeout: float = 60.0,
) -> str:
    """Send one private text prompt and return the model's text response.

    ``api_key`` defaults to the ``OPENAI_API_KEY`` environment variable.
    ``model`` is required so callers choose the model explicitly. The prompt
    is sent over HTTPS and is not printed, cached, or included in exceptions.

    Args:
        prompt: User text to send.
        model: Responses API model name.
        api_key: API key, or ``OPENAI_API_KEY`` when omitted.
        instructions: Optional developer/system-level instruction.
        max_output_tokens: Optional upper bound for generated tokens.
        timeout: Request timeout in seconds.
    """
    if not isinstance(prompt, str) or not prompt.strip():
        raise OpenAIConfigurationError("prompt must be a non-empty string")
    if not isinstance(model, str) or not model.strip():
        raise OpenAIConfigurationError("model must be a non-empty string")
    if timeout <= 0:
        raise OpenAIConfigurationError("timeout must be greater than zero")
    if max_output_tokens is not None and (
        not isinstance(max_output_tokens, int) or max_output_tokens <= 0
    ):
        raise OpenAIConfigurationError("max_output_tokens must be a positive integer")

    key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIConfigurationError(
            "set OPENAI_API_KEY or pass api_key explicitly"
        )

    payload: dict[str, Any] = {
        "model": model,
        "input": prompt,
        "store": False,
    }
    if instructions is not None:
        payload["instructions"] = instructions
    if max_output_tokens is not None:
        payload["max_output_tokens"] = max_output_tokens

    request = urllib.request.Request(
        API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = response.read()
    except urllib.error.HTTPError as exc:
        # Do not expose the response body: providers can echo request details
        # in an error, which would defeat the module's privacy guarantee.
        request_id = exc.headers.get("x-request-id") if exc.headers else None
        suffix = f" (request id: {request_id})" if request_id else ""
        raise OpenAIAPIError(
            f"OpenAI API returned HTTP {exc.code}{suffix}"
        ) from None
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise OpenAIAPIError("unable to reach the OpenAI API") from exc

    try:
        data = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise OpenAIAPIError("OpenAI API returned invalid JSON") from exc

    return _extract_text(data)


def _extract_text(data: Mapping[str, Any]) -> str:
    """Extract text from a Responses API JSON object."""
    direct = data.get("output_text")
    if isinstance(direct, str):
        return direct

    parts: list[str] = []
    for item in data.get("output", []):
        if not isinstance(item, Mapping):
            continue
        for content in item.get("content", []):
            if not isinstance(content, Mapping):
                continue
            text = content.get("text")
            if isinstance(text, str):
                parts.append(text)

    if parts:
        return "".join(parts)
    raise OpenAIAPIError("OpenAI API response contained no output text")


__all__ = [
    "OpenAIAPIError",
    "OpenAIConfigurationError",
    "OpenAIError",
    "send_prompt",
]
